tool.command:
ln -s $input_stats_pt_path ./input_stats_pt_path.$input_stats_pt_path.ext; #if $config_json: ln -s $config_json ./config_json.$config_json.ext; #end if
build_model
#if $config_json: --config ./config_json.$config_json.ext #end if
--input_stats_pt_path ./input_stats_pt_path.$input_stats_pt_path.ext #if $outname_output_model_pth_path: --output_model_pth_path $outname_output_model_pth_path #end if ;
if test -f $outname_output_model_pth_path; then mv $outname_output_model_pth_path $output_model_pth_path; fi;
